data class Order private constructor(
    val id: OrderId,
    val customerId: CustomerId,
    val lines: List<OrderLine>,
) {
    fun total(): Money = lines.fold(Money.ZERO) { acc, l -> acc + l.price }

    fun addLine(line: OrderLine): Either<OrderError, Order> =
        if (total() + line.price > LIMIT) OrderError.LimitExceeded.left()
        else copy(lines = lines + line).right()

    companion object {
        fun open(c: CustomerId): Order = Order(OrderId.new(), c, emptyList())
    }
}
